    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    for (int base = 0; base < n; base += blockDim.x) {
        const int source_index = base + threadIdx.x;
        int tile_count = n - base;
        if (tile_count > blockDim.x) {
            tile_count = blockDim.x;
